"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["5548"],{460(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>h,frontMatter:()=>r,contentTitle:()=>s,toc:()=>l,assets:()=>c});var o=JSON.parse('{"id":"how-to/hardware/devMgt_howto","title":"How to manage your device from AirVantage","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/how-to/hardware/devMgt_howto.md","sourceDirName":"how-to/hardware","slug":"/how-to/hardware/devMgt_howto","permalink":"/personal-av-docs/docs/how-to/hardware/devMgt_howto","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/how-to/hardware/devMgt_howto.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to manage your device from AirVantage","sidebar_label":"How to manage your device from AirVantag","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/howto/hardware/devMgt_howto","format":"md"}}'),a=n(4848),i=n(8453);let r={title:"How to manage your device from AirVantage",sidebar_label:"How to manage your device from AirVantag",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/howto/hardware/devMgt_howto",format:"md"},s,c={},l=[];function d(e){let t={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(t.p,{children:[":::note Edition\n",(0,a.jsx)(t.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,a.jsx)(t.a,{href:"https://doc.airvantage.net/av/howto/hardware/devMgt_howto",children:"Original page"}),".\n:::"]}),"\n",(0,a.jsx)(t.p,{children:"How to manage your device from AirVantage\nThis tutorial aims to explain how to manage your device remotely using AirVantage. In\nDevice Management\n, we include:\nUpgrade\nyour applications in the device (module or host) like the firmware or the software\nMonitor\nyour connectivity, your device, your application(s)\nBe able to\nact\non your device to reboot, reset to factory, change configuration in your device, \u2026\nFollow this tutorial to learn how to do this for a single device or for a set of devices.\n1 /\nUpgrade\n2 /\nMonitor\n3 /\nAct\nStep 1: How to upgrade your device\nIn AirVantage, you can ugrade a Sierra Wireless firmware and install or upgrade a software application. This section explains how to do both on a single device or on a fleet of devices.\nUpgrade your firmware over the air\nAll official Sierra Wireless Firmwares are already available in AirVantage, so you just have to select which to install on your device. According to packages available, AirVantage will select the one in this order of priority:\nSelect the delta package with reverse package between the current firmware version and the new one\nSelect the delta package between the current firmware version and the new one\nSelect the full package\nTo upgrade your device, follow these steps:\nGo to Monitor > Systems\nSelect your systems:\nSelect your systems by filtering using firmware version, labels, \u2026\nClick on the Upgrade button\nSelect your firmware:\nClick on the\nSearch an application\nbutton in the Applications line\nIn Public Applications tab, filter with the name of your module (for example HL8528)\nSelect the correct firmware version\nHow to find the firmware version\nTo get the firmware version (and more), open a serial port terminal (like Tera Term, \u2026). For Open AT modules, send the following AT command:\nati3\nRHL85xx.5.14.0.5.2.20160603.x6255\nOK\nFor Legato modules, send the following legato command:\ncm info\nDevice:      WP8548\nIMEI:        3599XXXXXXXX\nFSN:         LLYYYYYYYYYY\nFirmware:    SWI9X15Y_07.VV.VV.VV\nBootloadder: SWI9X15Y_07.VV.VV.VV\nAccording to your module or gateway, the command to get the Firmware version may vary. Please read the module manual to get the correct command.\nClick on\nUpgrade Firmware\nbutton\nOMA-DM Firmware upgrade Consumption\nWarning:\nthe bandwidth may vary according to the network context (quality, signal strenght, network errors, \u2026)\nDM Session:\nDM session initiation from client with authenticating info: 398 bytes\nResponse from server which authenticates client, authenticates itself to the client and requests firmware version and Key Index on client: 363 bytes. Client has 5 minutes to reply.\nClient authenticates server and sends firmware version to server: 232 bytes\nServer sends the update pkg descriptor URL: 277 bytes\nClient acknowledges the URL (Client has 5 minutes to acknowledge): 186 bytes\nServer sends the exec command to client to download the update pkg descriptor: 217 bytes\nClient acknowledges the exec command: 183 bytes\nServer terminates the session: 174 bytes\nHTTP Download:\nClient requests the update package download descriptor: Simple HTTP GET request\nServer responds with the download descriptor (XML) which contains the update package URL: 397 bytes\nClient requests the update package: Simple HTTP GET request\nServer responds with the update package: Payload size is the size of the update package\nDM Session to send Firmware update status:\nDM session initiation from client with authenticating info and firmware update status: 399 bytes\nResponse from server which authenticates client, acknowledges the firmware update status and terminates the session: 386 bytes\nYou can proceed to install firmware application in the System Details View (from the toolbar) as well.\nInstall or upgrade your software over the air\nRelease your Software Application in AirVantage\nBefore using an application with your system, you have to release and publish it (make it available for upgrade and installation) on AirVantage.\nFollow this\ntutorial\nto release your application.\nInstallation\nTo upgrade the software application of your device, follow these steps:\nGo to Monitor > Systems\nSelect your systems:\nSelect your systems by filtering using software version, labels, \u2026\nClick on the More menu and\nInstall software\nSelect your software:\nClick on the\nSearch an application\nbutton in the Applications line\nIn\nMy Apps\nApplications tab, filter with the name of your software (for example\nGreenhouse\n)\nSelect the correct software version\nClick on\nInstall Application\nbutton\nYou can proceed to install software application in the System Details View (from the top menu or using the System Applications widget) as well.\nStep 2: How to monitor your device\nTo monitor your device, you can use:\nsynchronization\n: you can manually request a synchronization between your device and AirVantage\nconfigure a\nDefault Status Report\nto be sent to AirVantage\nconfigure a custom\nAdditional Dataset\nto be sent to AirVantage\nRetrieve\na custom set of data manually\nStatus report & heartbeat consumption\nWarning:\nthe bandwidth may vary according to the network context (quality, signal strength, network errors, \u2026)\nA simple heartbeat is 1-2KB.\nStatus Report:\n5 status reports with 10 values (SL6087):\n7 808B\n8 087B\n5 816B\n5 945B\n6 377B\nAverage: 6 806B\nEcIo, CCid, IpAd has not be sent.\nIt includes:\nA simple Polling request from device to the server\nServer send READ request to the device\nThe device sends the 10 values to the devices.\nData monitoring:\n100 data (about 36 289B):\n1641B: Http header\n448B: OMA DM header\n34.2KB: data\nSynchronize the device information on AirVantage\nThe synchronization fills or updates all the information from your system in AirVantage about device and connectivity. All this information can be viewed in the System Info widget you can access from Monitor > Systems > System\u2019s details:\nYou can then configure the communication of your system in order to get a status report regularly from your device using the configure communication button in the top of the screen. Have a look at this\nHow to\n.\nHow to synchronize your system\nFirst, go to the system detail view\nClick on the\nSynchronize\nbutton in the top menu bar\nClick on\nSynchronize System\nA new operation is created which will be completed once the device communicates all the information to AirVantage.\nConfigure a Default Status Report or an Additional Dataset\nHave a look at this\ntutorial\nto enable and configure the default status report.\nRetrieve data from one or several systems\nHave a look at this\ntutorial\nto retrieve a set of data using a dataset.\nStep 3: How to act on your device\nThe last section describes how to reboot your device, reset to factory (when it is available), change the configuration in your device, send a SMS, wake up your device.\nBoth of them can be applied on a single device (from the System Detail View) or a set of devices (from Monitor > Systems view).\nEach of these commands is prepared as an operation. Once the device communicates with AirVantage, they are requested from the device. You can use the Wake Up mechanism, when available, to generate a communication between the device and AirVantage.\nReboot & Reset to factory: these commands are available in the toolbar in Monitor > Systems or in the System Detail View.\nConfigure your device\nto modify its behavior.\nSend a SMS/Wake Up SMS: a text SMS is sent to the device if a\nSMS provider\nhas been configured in AirVantage. Wake Up SMS is a binary SMS your device understands and which generates a communication to AirVantage."})]})}function h(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>s});var o=n(6540);let a={},i=o.createContext(a);function r(e){let t=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);